1	// See elf_syms.hpp. Reads the ELF .symtab directly (no `nm` shell-out).
2	#include "elf_syms.hpp"
3	
4	#include <cstdint>
5	#include <cstring>
6	#include <fstream>
7	#include <sstream>
8	#include <vector>
9	
10	#include <elf.h>
11	
12	namespace andes_sim {
13	namespace {
14	
15	// Lowercase, minimal-width hex -- matches the bare hex a stripped "0x" address
16	// yields, so a symbol and its literal address resolve to the same string.
17	std::string to_hex(uint64_t v) {
18	  std::ostringstream ss;
19	  ss << std::hex << v;
20	  return ss.str();
21	}
22	
23	bool slurp(const std::string& path, std::vector<char>& buf) {
24	  std::ifstream f(path, std::ios::binary);
25	  if (!f) return false;
26	  std::ostringstream ss;
27	  ss << f.rdbuf();
28	  const std::string s = ss.str();
29	  buf.assign(s.begin(), s.end());
30	  return true;
31	}
32	
33	// memcpy a POD header out of the buffer at `off`; false if it would overrun
34	// (buffers may be truncated/malformed -- never read past the end).
35	template <class T>
36	bool load(const std::vector<char>& buf, size_t off, T& out) {
37	  if (off + sizeof(T) > buf.size()) return false;
38	  std::memcpy(&out, buf.data() + off, sizeof(T));
39	  return true;
40	}
41	
42	}  // namespace
43	
44	std::string resolve_pc(const std::string& elf_path, const std::string& boundary,
45	                       std::string& err) {
46	  err.clear();
47	
48	  // A "0x"/"0X" address is used verbatim with the prefix stripped (roi.sh
49	  // `${boundary#0[xX]}`); the .symtab is never touched.
50	  if (boundary.starts_with("0x") || boundary.starts_with("0X")) {
51	    std::string addr = boundary.substr(2);
52	    if (addr.empty()) {
53	      err = "malformed address '" + boundary + "'";
54	      return "";
55	    }
56	    return addr;
57	  }
58	
59	  std::vector<char> buf;
60	  if (!slurp(elf_path, buf)) {
61	    err = "cannot read ELF '" + elf_path + "'";
62	    return "";
63	  }
64	
65	  Elf64_Ehdr eh;
66	  if (!load(buf, 0, eh) || std::memcmp(eh.e_ident, ELFMAG, SELFMAG) != 0) {
67	    err = "not an ELF file: " + elf_path;
68	    return "";
69	  }
70	  if (eh.e_ident[EI_CLASS] != ELFCLASS64) {
71	    err = "not an RV64 (ELFCLASS64) file: " + elf_path;
72	    return "";
73	  }
74	
75	  // Scan section headers for a symbol table; resolve names through its linked
76	  // string table (sh_link).
77	  for (unsigned i = 0; i < eh.e_shnum; ++i) {
78	    Elf64_Shdr sym_sh;
79	    if (!load(buf, eh.e_shoff + static_cast<size_t>(i) * eh.e_shentsize, sym_sh))
80	      break;
81	    if (sym_sh.sh_type != SHT_SYMTAB || sym_sh.sh_entsize == 0) continue;
82	
83	    Elf64_Shdr str_sh;
84	    if (sym_sh.sh_link >= eh.e_shnum ||
85	        !load(buf, eh.e_shoff + static_cast<size_t>(sym_sh.sh_link) * eh.e_shentsize,
86	              str_sh))
87	      continue;
88	
89	    const size_t nsym = sym_sh.sh_size / sym_sh.sh_entsize;
90	    for (size_t s = 0; s < nsym; ++s) {
91	      Elf64_Sym sym;
92	      if (!load(buf, sym_sh.sh_offset + s * sym_sh.sh_entsize, sym)) break;
93	      if (sym.st_shndx == SHN_UNDEF) continue;  // --defined-only
94	
95	      const size_t noff = str_sh.sh_offset + sym.st_name;
96	      if (noff >= buf.size()) continue;
97	      const char* name = buf.data() + noff;
98	      const size_t avail = buf.size() - noff;
99	      if (::strnlen(name, avail) == avail) continue;  // unterminated in bounds
100	      if (boundary == name) return to_hex(sym.st_value);
101	    }
102	  }
103	
104	  err = "symbol '" + boundary + "' not defined in " + elf_path;
105	  return "";
106	}
107	
108	}  // namespace andes_sim
