66	constexpr int kDescribeTimeoutMs = 5000;
67	
68	bool is_executable_file(const fs::path& p) {
69	  std::error_code ec;
70	  if (!fs::is_regular_file(p, ec)) return false;
71	  return ::access(p.c_str(), X_OK) == 0;
72	}
73	
74	std::string read_file(const fs::path& p) {
75	  std::ifstream f(p, std::ios::binary);
76	  std::ostringstream ss;
77	  ss << f.rdbuf();
78	  return ss.str();
79	}
80	
81	// Ask one binary to describe itself: try `<bin> --describe`, else read the
82	// <bin>.json sidecar. On success fills `d` and returns true; on failure leaves
83	// a human-readable note in `warn`.
84	bool describe_one(const fs::path& bin, EngineDescriptor& d, std::string& warn) {
85	  RunResult r = run_process({bin.string(), "--describe"}, kDescribeTimeoutMs);
86	  if (!r.spawn_failed && !r.timed_out && r.rc == 0) {
87	    json::Parsed p = json::parse(r.out);
88	    if (p.ok) {
89	      std::string err = descriptor_from_json(p.value, d);
90	      if (err.empty()) {
91	        d.bin_path = bin.string();
92	        d.source = "--describe";
93	        return true;
94	      }
95	      warn = bin.string() + ": --describe JSON invalid: " + err;
96	    } else {
97	      warn = bin.string() + ": --describe output is not JSON: " + p.error;
98	    }
99	  }
100	
101	  fs::path sidecar = bin;
102	  sidecar += ".json";
103	  std::error_code ec;
104	  if (fs::exists(sidecar, ec)) {
105	    json::Parsed p = json::parse(read_file(sidecar));
106	    if (p.ok) {
107	      EngineDescriptor sd;
108	      std::string err = descriptor_from_json(p.value, sd);
109	      if (err.empty()) {
110	        sd.bin_path = bin.string();
111	        sd.source = "sidecar";
112	        d = std::move(sd);
113	        return true;
114	      }
115	      warn = sidecar.string() + ": invalid descriptor: " + err;
116	    } else {
117	      warn = sidecar.string() + ": not JSON: " + p.error;
118	    }
119	  }
120	
121	  if (warn.empty()) warn = bin.string() + ": no --describe and no sidecar";
122	  return false;
123	}
124	
125	// `prefix` filters candidate basenames; empty accepts any executable. The
126	// default verilator/build scan passes "sim_"; a user-curated engines dir passes
127	// "" so a drop-in alioth/sid (any name) is eligible. The naming convention thus
128	// lives in the call site, not in this engine-agnostic scanner.
129	void scan_dir(const fs::path& dir, std::string_view prefix, Discovery& out,
130	              std::set<std::string>& seen) {
131	  std::error_code ec;
132	  if (!fs::is_directory(dir, ec)) return;
133	
134	  std::vector<fs::path> entries;
135	  for (const auto& e : fs::directory_iterator(dir, ec)) entries.push_back(e.path());
136	  std::sort(entries.begin(), entries.end());  // stable, deterministic order
137	
138	  for (const fs::path& p : entries) {
139	    if (!prefix.empty() && !p.filename().string().starts_with(prefix)) continue;
140	    if (!is_executable_file(p)) continue;
141	    EngineDescriptor d;
142	    std::string warn;
143	    if (describe_one(p, d, warn)) {
144	      if (seen.insert(d.id).second) out.engines.push_back(std::move(d));
145	    } else if (!warn.empty()) {
146	      out.warnings.push_back(warn);
147	    }
148	  }
149	}
150	
151	}  // namespace
