85	std::vector<std::vector<std::string>> plan_argvs(
86	    const Plan& plan, const std::vector<EngineDescriptor>& engines,
87	    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
88	  std::vector<std::vector<std::string>> out;
89	  out.reserve(plan.steps.size());
90	  std::string prev_state_out;  // empty for the cold first leg
91	
92	  for (size_t i = 0; i < plan.steps.size(); ++i) {
93	    const Step& step = plan.steps[i];
94	    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
95	    if (!eng) {
96	      err = "plan step " + std::to_string(i) + ": unknown engine '" +
97	            step.engine_id + "'";
98	      return {};
99	    }
100	    const std::vector<std::string>* tmpl = eng->invoke_for(step.role);
101	    if (!tmpl) {
102	      err = "plan step " + std::to_string(i) + ": engine '" + step.engine_id +
103	            "' has no invoke template for role '" + step.role + "'";
104	      return {};
105	    }
106	
107	    std::string trig_err;
108	    const LegTriggerArgs lt = leg_trigger_args(step.trigger, step.role, trig_err);
109	    if (!trig_err.empty()) {
110	      err = "plan step " + std::to_string(i) + ": " + trig_err;
111	      return {};
112	    }
113	
114	    const std::string state_out = state_path(workdir, i);
115	    const std::map<std::string, std::string> m = {
116	        {"bin", eng->bin_path},
117	        {"elf", plan.elf},
118	        {"plugin", ctx.plugin_path},
119	        {"mmap", ctx.mmap_path},
120	        {"mmap_size", std::to_string(ctx.mem_size)},
121	        {"mmap_base", ctx.mmap_base},
122	        {"state_in", prev_state_out},
123	        {"state_out", state_out},
124	        {"trigger", lt.plugin_suffix},  // qemu plugin comma-suffix (empty for csr)
125	    };
126	    std::vector<std::string> argv = build_argv(*tmpl, m, err);
127	    if (!err.empty()) {
128	      err = "plan step " + std::to_string(i) + ": " + err;
129	      return {};
130	    }
131	    // Trigger's vsim tokens, then user-forwarded per-leg flags -- both verbatim
132	    // after the filled template (matches tests/e2e.sh's ordering).
133	    argv.insert(argv.end(), lt.extra.begin(), lt.extra.end());
134	    argv.insert(argv.end(), step.extra_args.begin(), step.extra_args.end());
135	    out.push_back(std::move(argv));
136	    prev_state_out = state_out;
137	  }
138	  err.clear();
139	  return out;
140	}
141	
142	PlanResult run_plan(const Plan& plan,
143	                    const std::vector<EngineDescriptor>& engines,
144	                    const PlanOptions& opts) {
145	  PlanResult res;
146	  if (plan.steps.empty()) {
147	    res.error = "plan has no steps";
148	    return res;
149	  }
150	
151	  // Acquire the shared mmap: allocate one (and own it) when none is pinned.
152	  std::string mmap_path = plan.mmap_path;
153	  const bool own_mmap = mmap_path.empty();
154	  if (own_mmap) {
155	    std::string err;
156	    mmap_path = allocate(plan.mem_size, err);
157	    if (mmap_path.empty()) {
158	      res.error = err;
159	      return res;
160	    }
161	  }
162	
163	  // A private dir for the threaded drain files.
164	  std::error_code ec;
165	  fs::path workdir = fs::temp_directory_path(ec) / "andes-sim-plan-XXXXXX";
166	  std::string tmpl = workdir.string();
167	  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
168	  tbuf.push_back('\0');
169	  const char* made = ::mkdtemp(tbuf.data());
170	  if (!made) {
171	    if (own_mmap) ::unlink(mmap_path.c_str());
172	    res.error = "failed to create plan work dir";
173	    return res;
174	  }
175	  const std::string wd = made;
176	
177	  RuntimeCtx ctx;
178	  ctx.mmap_path = mmap_path;
179	  ctx.mem_size = plan.mem_size;
180	  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps its "0x0" default
181	
182	  std::string err;
183	  const std::vector<std::vector<std::string>> argvs =
184	      plan_argvs(plan, engines, wd, ctx, err);
185	  if (!err.empty()) {
186	    res.error = err;
187	  } else {
188	    for (size_t i = 0; i < argvs.size(); ++i) {
189	      const RunResult r = run_process(argvs[i], opts.timeout_ms);
190	      if (r.spawn_failed) {
191	        res.error = "plan step " + std::to_string(i) + ": failed to spawn";
192	        break;
193	      }
194	      if (r.timed_out) {
195	        res.error = "plan step " + std::to_string(i) + ": timed out after " +
196	                    std::to_string(opts.timeout_ms) + " ms";
197	        break;
198	      }
199	      if (r.rc != opts.expect_rc) {
200	        res.error = "plan step " + std::to_string(i) + ": expected exit " +
201	                    std::to_string(opts.expect_rc) + ", got " +
202	                    std::to_string(r.rc);
203	        break;
204	      }
205	      const StateFile sf = read_state_file(state_path(wd, i));
206	      if (!sf.ok()) {
207	        res.error = "plan step " + std::to_string(i) + ": " + sf.error;
208	        break;
209	      }
210	      res.phases.push_back({sf.st.mcycle, sf.st.minstret});
211	    }
212	  }
213	
214	  fs::remove_all(wd, ec);
215	  if (own_mmap) ::unlink(mmap_path.c_str());
216	  return res;
217	}
