41	// the self-describe half of the framework's hot-plug contract: andes-sim runs
42	// `sim_<cfg> --describe`, parses this JSON, and can then drive the binary with
43	// no per-engine code. vlen/xlen come from the same embedded config.inc blob
44	// that --print-config dumps; the config name comes from VSIM_CPU_PYMODULE_NAME.
45	static void describe_engine()
46	{
47	  std::string cfg = VSIM_CPU_PYMODULE_NAME;  // "simulator_<cfg>"
48	  const std::string prefix = "simulator_";
49	  if (cfg.starts_with(prefix))
50	    cfg = cfg.substr(prefix.size());
51	
52	  const std::string_view blob(&_binary_config_inc_start,
53	                              static_cast<size_t>(&_binary_config_inc_end
54	                                                  - &_binary_config_inc_start));
55	  auto scan_int = [blob](std::string_view key) -> long {
56	    size_t pos = blob.find(key);
57	    if (pos == std::string_view::npos)
58	      return 0;
59	    pos += key.size();
60	    while (pos < blob.size() && (blob[pos] < '0' || blob[pos] > '9'))
61	      ++pos;
62	    long v = 0;
63	    while (pos < blob.size() && blob[pos] >= '0' && blob[pos] <= '9')
64	      v = v * 10 + (blob[pos++] - '0');
65	    return v;
66	  };
67	  const long vlen = scan_int("NDS_VLEN");
68	  const long xlen = scan_int("NDS_XLEN");
69	
70	  // Built by hand (not fmt) to keep the literal {bin}/{elf}/{state_in}
71	  // placeholders out of fmt's brace parser.
72	  std::string json;
73	  json += "{\n";
74	  json += "  \"id\": \"verilator:" + cfg + "\",\n";
75	  json += "  \"type\": \"verilator\",\n";
76	  json += "  \"kind\": \"cycle-accurate\",\n";
77	  json += "  \"vlen\": " + std::to_string(vlen) + ", \"xlen\": "
78	          + std::to_string(xlen) + ",\n";
79	  json += "  \"triggers\": [\"csr\", \"pc\", \"icount\"],\n";
80	  json += "  \"roles\": [\"standalone\", \"accurate-leg\"],\n";
81	  json += "  \"state\": [\"resume\", \"drain\"],\n";
82	  json += "  \"invoke\": {\n";
83	  json += "    \"standalone\": [\"{bin}\", \"{elf}\"],\n";
84	  json += "    \"accurate-leg\": [\"{bin}\", \"{elf}\", "
85	          "\"--resume-from-qemu\", \"{state_in}\", "
86	          "\"--handoff-out\", \"{state_out}\", "
87	          "\"--shared-mem-path\", \"{mmap}\", "
88	          "\"--shared-mem-size\", \"{mmap_size}\", "
89	          "\"--shared-mem-base\", \"{mmap_base}\"]\n";
90	  json += "  },\n";
91	  json += "  \"result\": \"stderr:cycles\"\n";
92	  json += "}\n";
93	  fwrite(json.data(), 1, json.size(), stdout);
94	}
